# Script S3. Monthly nighttime water temperature summaries per logger# Thermal Behavior of Crocodile Caves in Central Belize# Authors: Wynne, J.J., Shaffer, I.N., Roberts, J.# Script Author: J. Judson Wynne# R-Studio Version: 2025.05.1+513 (2025.05.1+513)# Required packages:# readxl # lubridate# tidyverse# Input File# CrocCave_Data.xlsx# Output:# Table 4 from paper# Summaries of monthly nighttime water temperatures per logger# Required packageslibrary(readxl)library(tidyverse)library(lubridate)# Thermal threshold (¡C)threshold <- 24.22# Settingsxlsx_file <- "CrocCave_Data.xlsx"winter_start <- as.POSIXct("2022-11-01 00:00:00")winter_end <- as.POSIXct("2023-02-18 23:59:59")# Import all worksheetssheets <- excel_sheets(xlsx_file); dat <- map_dfr(sheets, function(sh){read_excel(xlsx_file, sheet = sh) %>% mutate(Sheet = sh, Logger = str_extract(sh, "L[1-5]"), Cave = ifelse(str_detect(sh, "Croc2"), "Croc 2", "KHC"))})# Create DateTimedat <- dat %>% mutate(DateTime = as.POSIXct(paste(format(Date, "%Y-%m-%d"), format(Time, "%H:%M:%S")), format = "%Y-%m-%d %H:%M:%S"), Temp = `Temperature (C)`, Hour = hour(DateTime))# Winter subsetdat_winter <- dat %>% filter(DateTime >= winter_start, DateTime <= winter_end)# Nighttime conditions# Night defined as 1900-0600 hnight <- dat_winter %>% filter(Hour >= 19 | Hour <= 6) %>% mutate(Month = format(DateTime, "%Y-%m"), NightDate = as.Date(DateTime)); night$NightDate[night$Hour <= 5] <- night$NightDate[night$Hour <= 5] - 1# Table 4# Monthly nighttime water-temperature summaries by logger# Monthly median nighttime temperaturetable4_median <- night %>% summarize(MedianTemp = median(Temp, na.rm = TRUE), .by = c(Cave, Logger, Month))# Percentage of nights per month exceeding the thermal thresholdtable4_pct <- night %>% summarize(AboveThreshold = median(Temp, na.rm = TRUE) > threshold, .by = c(Cave, Logger, Month, NightDate)) %>% summarize(PercentNights = 100 * mean(AboveThreshold), .by = c(Cave, Logger, Month))# Final tabletable4 <- left_join(table4_median, table4_pct, by = c("Cave", "Logger", "Month")) %>% arrange(Cave, Logger, Month) %>% mutate(MedianTemp = round(MedianTemp, 2), PercentNights = round(PercentNights, 2)) %>% rename(`Nights > 24.22C (%)` = PercentNights)# Export tablewrite.csv(table4, "Table4_MoLogNight.csv", row.names = FALSE)